// XOR two global states for delta encoding
for (std::size_t i = 0; i < sizeof(lfs_gstate_t)/sizeof(lfs_block_t); i++) {
    reinterpret_cast<lfs_block_t*>(a)[i] ^= reinterpret_cast<const lfs_block_t*>(b)[i];
}

// Special handling for block pairs (common in global state)
if (a->type == LFS_TYPE_MOVESTATE) {
    lfs_block_t pair_a[2] = {a->from, a->to};
    lfs_block_t pair_b[2] = {b->from, b->to};
    lfs_block_t result[2] = {0};

    // XOR each block in the pair
    result[0] = pair_a[0] ^ pair_b[0];
    result[1] = pair_a[1] ^ pair_b[1];

    // Handle null blocks specially
    if (result[0] == LFS_BLOCK_NULL) result[0] = LFS_BLOCK_NULL;
    if (result[1] == LFS_BLOCK_NULL) result[1] = LFS_BLOCK_NULL;

    a->from = result[0];
    a->to = result[1];
}

// Handle CRC if present in global state
if (a->crc != 0) {
    a->crc ^= b->crc;
}

